export function uncertain(i: u32, n: u32, value: f64): f64 {
  const a: f64[] = [1.0, 2.0];
  const alias = a;
  alias[i] = a[0];
  a[2] = value;
  alias.length = n;
  a.length = 4294967295;
  return a[4294967294];
}

