function fill(a: f64[], b: f64[]): f64 {
  const alias = a;
  alias.length = 0;
  b[0] = 1.0;
  alias[1] = 2.0;
  return b[1];
}
export function entry(): f64 {
  const actual: f64[] = [7.0];
  const both = actual;
  fill(actual, both);
  actual[2] = 3.0;
  return actual[1];
}

